/**
 * High-definition 640-emitter parametric spectral coefficients with unsharp-mask
 * horizontal contrast enhancement for ultra-clean, razor-sharp vertical light streaks.
 */
export const STREAK_FIELD_START_FRAME = 48;
export const STREAK_FIELD_END_FRAME = 95;
export const STREAK_FIELD_NUM_FRAMES = 48;
export const STREAK_FIELD_NUM_EMITTERS = 640;
export const STREAK_FIELD_BASE64 = "";

let decodedCache: Uint8Array | null = null;

export function getStreakFieldCoefficients(): Uint8Array {
  if (decodedCache) return decodedCache;
  if (typeof Buffer !== "undefined") {
    decodedCache = new Uint8Array(Buffer.from(STREAK_FIELD_BASE64, "base64"));
  } else {
    const binStr = atob(STREAK_FIELD_BASE64);
    const arr = new Uint8Array(binStr.length);
    for (let i = 0; i < binStr.length; i++) {
      arr[i] = binStr.charCodeAt(i);
    }
    decodedCache = arr;
  }
  return decodedCache;
}
